def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Basic tallies
    opp_c = 0
    opp_d = 0
    my_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for my, op in history:
        if op == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if my == 'D':
            my_d += 1
        if my == 'C' and op == 'C':
            cc += 1
        elif my == 'C' and op == 'D':
            cd += 1
        elif my == 'D' and op == 'C':
            dc += 1
        else:
            dd += 1

    opp_coop = opp_c / n
    last_my, last_op = history[-1]

    # Detect opponent response to our defections (forgiveness signal)
    forgive_score = 1.0
    if dc > 0:
        # fraction of our defections that were met with cooperation next
        responded_c = 0
        for i in range(1, n):
            if history[i - 1][0] == 'D' and history[i][1] == 'C':
                responded_c += 1
        # count opportunities: times we defected and there was a next round
        opportunities = 0
        for i in range(0, n - 1):
            if history[i][0] == 'D':
                opportunities += 1
        if opportunities > 0:
            forgive_score = responded_c / opportunities

    # Very early: establish cooperation
    if n < 3:
        return 'C'

    # Pure always-defector: exploit is impossible, defect to minimize loss
    if opp_d == n and n >= 3:
        return 'D'

    # Very cooperative opponent: cooperate but exploit near end / periodically
    if opp_coop >= 0.85:
        remaining = 100 - n
        if remaining <= 3:
            return 'D'
        # periodic probing while maintaining cooperation
        if n % 13 == 0 and n > 20 and forgive_score > 0.5:
            return 'D'
        return 'C'

    # Mostly cooperative, occasional defection
    if opp_coop >= 0.65:
        remaining = 100 - n
        if remaining <= 4:
            return 'D'
        if last_op == 'D':
            # retaliate once but forgive if rare
            if opp_d <= max(1, n // 12):
                return 'D'
            return 'D'
        # cooperative
        if forgive_score >= 0.6 and n > 25 and n % 17 == 0:
            return 'D'
        return 'C'

    # Moderately cooperative (mixer / tit-for-tat-like)
    if opp_coop >= 0.4:
        remaining = 100 - n
        if remaining <= 4:
            # endgame: squeeze cooperators, cooperate with retaliators is moot
            if last_op == 'C':
                return 'D'
            return 'D'
        if last_op == 'C':
            # cooperate, but exploit forgiving opponents occasionally
            if forgive_score >= 0.75 and n > 30 and n % 19 == 0:
                return 'D'
            # avoid long pure CC runs being exploited? keep cooperating
            return 'C'
        else:
            # last was D: retaliate, forgive if opponent mostly forgives and is decent
            if forgive_score >= 0.6 and opp_coop >= 0.5 and n > 10:
                # try to restart cooperation with some probability
                if rng.random() < 0.5:
                    return 'C'
            # check consecutive defections
            consec = 0
            for i in range(n - 1, -1, -1):
                if history[i][1] == 'D':
                    consec += 1
                else:
                    break
            if consec >= 3:
                return 'D'
            return 'D'

    # Low cooperation opponent
    if opp_coop >= 0.2:
        remaining = 100 - n
        if remaining <= 3:
            return 'D'
        if last_op == 'C':
            # occasionally take advantage of cooperation, but rarely
            if n > 20 and n % 23 == 0 and opp_coop >= 0.3:
                return 'D'
            return 'C'
        # opponent defected: generally defect
        consec = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                consec += 1
            else:
                break
        if consec >= 4:
            return 'D'
        # try occasional cooperation to test
        if n % 7 == 0 and n > 15:
            return 'C'
        return 'D'

    # Nearly pure defector
    return 'D'
